<?php require '_layout.php';$pdo=db();$materialId=(int)($_GET['material_id']??0);$material=[];if($pdo){$q=$pdo->prepare('SELECT * FROM materials WHERE id=?');$q->execute([$materialId]);$material=$q->fetch(PDO::FETCH_ASSOC)?:[];}$edit=isset($_GET['id']);$color=['id'=>'','code'=>'','image'=>'','hex_code'=>''];if($edit&&$pdo){$q=$pdo->prepare('SELECT * FROM material_colors WHERE id=? AND material_id=?');$q->execute([(int)$_GET['id'],$materialId]);$color=$q->fetch(PDO::FETCH_ASSOC)?:$color;}if(!$material){header('Location: materials.php?error=Không tìm thấy chất liệu');exit;}admin_header($edit?'Chỉnh sửa màu':'Thêm màu','materials');?><section class="form-page narrow"><div class="form-heading"><div><a class="back" href="material-form.php?id=<?=$materialId?>"><i class="bi bi-arrow-left"></i> Quay lại <?=htmlspecialchars($material['name'])?></a><h2><?=$edit?'Chỉnh sửa':'Thêm'?> màu</h2><p><?=$edit?'Upload ảnh mới để thay thế màu hiện tại.':'Chọn nhiều ảnh để thêm nhiều màu cùng lúc; mỗi ảnh tạo một màu riêng.'?></p></div></div><form class="color-form form-card" method="post" action="material-color-save.php" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$color['id']?>"><input type="hidden" name="material_id" value="<?=$materialId?>"><div class="field"><label>Ảnh màu <?=$edit?'':'*'?></label><input <?=$edit?'':'required'?> accept="image/jpeg,image/png,image/webp" type="file" name="images[]" <?=$edit?'':'multiple'?> data-color-image><small>Ví dụ upload <b>JS-02.jpg</b> sẽ tạo mã <b>JS-02</b>. HEX được tính từ màu trung bình của từng ảnh.</small></div><div class="two-fields"><div class="field"><label>Mã màu xem trước</label><input readonly value="<?=htmlspecialchars($color['code'])?>" data-color-code></div><div class="field"><label>HEX xem trước</label><input readonly value="<?=htmlspecialchars($color['hex_code'])?>" data-color-hex></div></div><?php if($color['image']):?><img class="color-large-preview" src="<?=htmlspecialchars($color['image'])?>" alt=""><?php endif?><button class="admin-button save"><?=$edit?'Lưu màu':'Thêm các màu'?></button></form></section><?php admin_footer(); ?>
